import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  Paper,
  Tab,
  Tabs,
  Box,
  MenuItem,
  Breadcrumbs,
  Link,
  Select,
  Button,
  FormHelperText,
  FormControl,
  InputLabel,
  Grid,
  Typography,
  MuiAlert
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";
import InfoIcon from "@material-ui/icons/Info";
import AddIcon from "@material-ui/icons/Add";
import BootstrapTable from "react-bootstrap-table-next";
import ToolkitProvider, { Search } from "react-bootstrap-table2-toolkit";
const { SearchBar } = Search;
class ProcessGroupDetail extends Component {
  state = {
    value: 1,
    columns: [
      {
        dataField: "record",
        text: "Edit Process"
      }
    ]
  };
  products = [
    {
      id: this.props.id,
      record: "Machining\nID:" + this.props.id
    },
    {
      id: "34905803945",
      record: "Assembly\nID:34905803945"
    },
    {
      id: "34905803945d",
      record: "Visual Validation\nID:34905803945"
    }
  ];
  onPageChangeClick = (navType, page, objId) => {
    const pageDetail = {
      navType,
      page,
      objId
    };
    this.props.changePage(pageDetail);
  };
  handleChange = (event, newValue) => {
    this.setState({ value: newValue });
  };
  onNewProcessSelect = event => {
    this.setState({ selectedProcess: event.target.value });
  };
  processAddButton = () => {
    console.log(this.state.selectedProcess);

    const newClient = {
      name: newData.name,
      userId: this.props.auth.isAuthenticated
        ? this.props.auth.user._id
        : "Guest"
    }; //
    if (
      this.props.auth.user.userAccess.access.COA_1_E ||
      this.props.auth.user.userAccess.access.COA_2_E ||
      this.props.auth.user.userAccess.access.COA_3_E ||
      this.props.auth.user.userAccess.access.COA_4_E ||
      this.props.auth.user.userAccess.access.COA_5_E ||
      this.props.auth.user.userAccess.access.COA_6_E
    ) {
      axios
        .post("/api/processData", newClient, tokenConfig(store.getState), {
          data: { user: this.props.auth.user._id }
        })
        .then(res => {
          console.log(res.data);
          this.retrieveFromDb();
        })
        .catch(err => console.log(err.data));
    } else {
      this.setState({
        msg: "Edit Access Not Authorized for User. Configurations Not Saved",
        snackBarAlertType: "error",
        snackBar: true
      });
    }
  };
  handleClose = (event, reason) => {
    this.setState({
      snackBar: !this.state.snackBar
    });
  };
  selectRow = {
    mode: "radio",
    clickToSelect: true,
    style: { backgroundColor: "#ededed" },
    onSelect: (row, isSelect, rowIndex, e) => {
      console.log(row.id);
      console.log(isSelect);
      console.log(rowIndex);
      console.log(e);
      this.setState({ value: rowIndex + 1 });
    }
  };

  render() {
    function renderPageSwitch(index) {
      switch (index) {
        case 1:
          return "Process UI 1";
        case 2:
          return "Process UI 2";
        case 3:
          return "Process UI 3";

        default:
          return "Undefined Tab Index";
      }
    }
    return (
      <div>
        <Snackbar
          open={this.state.snackBar}
          autoHideDuration={10000}
          onClose={this.handleClose}
        >
          <MuiAlert
            severity={this.state.snackBarAlertType}
            onClose={this.handleClose}
          >
            {this.state.msg}
          </MuiAlert>
        </Snackbar>
        <Grid container>
          <Grid item sm sm={12}>
            <Paper style={{ padding: 20, margin: 10 }}>
              <Breadcrumbs
                style={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Link
                  onClick={this.onPageChangeClick.bind(
                    this,
                    "MainNav",
                    "ProcessGroups",
                    0
                  )}
                  href="#"
                >
                  Process Groups
                </Link>

                <Typography color="textPrimary">
                  Process Group Details
                </Typography>
              </Breadcrumbs>
            </Paper>
            <Paper style={{ padding: 10, margin: 10 }}>
              <Grid container>
                <Grid item sm sm={4}>
                  <div title="Process groups are 1 or more processes.  Each processes uses item(s) and outputs item(s). Use process groups to group processes in any way you want. Some recommended ways of grouping are the following: 1. group processes that sequentially use the output item of the last process 2. Group proceses that are for one product 3. Place assembly processes in a standalone process group 4. place any process in a process group by itself if you like.  Really this tool is made for your own organization such as a file structure.">
                    <h4>
                      {""}
                      <InfoIcon /> Process Group Name: Ball Nut Production
                    </h4>
                    <p>Process Group ID:{this.props.id}</p>
                  </div>
                </Grid>

                <Grid item sm sm={4}>
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "center"
                    }}
                  >
                    <div title="Please select processes to add to the below process group.  This will add the process to this group for organization purposes.  Each process utilizes item(s) and generates item(s)">
                      <InfoIcon />{" "}
                      <FormControl style={{ minWidth: 200 }}>
                        <InputLabel id="demo-simple-select-helper-label">
                          Choose Process
                        </InputLabel>
                        <Select
                          labelId="demo-simple-select-helper-label"
                          onChange={this.onNewProcessSelect}
                        >
                          <MenuItem value={1}>Machining</MenuItem>
                          <MenuItem value={2}>Assembly</MenuItem>
                          <MenuItem value={3}>CMM Validation</MenuItem>
                          <MenuItem value={4}>Visual Validation</MenuItem>
                        </Select>
                      </FormControl>{" "}
                      <Button onClick={this.processAddButton}>
                        <AddIcon />
                      </Button>
                    </div>
                  </div>
                </Grid>

                <Grid item sm sm={4}></Grid>
              </Grid>
            </Paper>
          </Grid>
          <Grid item sm={2}>
            <Paper style={{ padding: 10, margin: 10 }}>
              {/*<Tabs
              orientation="vertical"
              variant="scrollable"
              value={this.state.value}
              onChange={this.handleChange}
            >
              <Tab label="Machining" value={1} />
              <Tab label="Assembly" value={2} />
              <Tab label="Visual Validation" value={3} />
            </Tabs>*/}

              {/*<BootstrapTable
              keyField="record"
              data={this.state.products}
              columns={this.state.columns}
            />*/}

              <ToolkitProvider
                keyField="record"
                data={this.products}
                columns={this.state.columns}
                search
              >
                {props => (
                  <div>
                    <SearchBar {...props.searchProps} />
                    <hr />
                    <BootstrapTable
                      {...props.baseProps}
                      hover
                      selectRow={this.selectRow}
                    />
                  </div>
                )}
              </ToolkitProvider>
            </Paper>
          </Grid>
          <Grid item sm sm={10}>
            <Paper style={{ padding: 20, margin: 10 }}>
              Process ID: askldflajsdfl; created by: User
            </Paper>
            <Paper style={{ padding: 20, margin: 10 }}>
              {renderPageSwitch(this.state.value)}
            </Paper>
          </Grid>
        </Grid>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ProcessGroupDetail);
